"""Flask microservice for resolving Vikunja task identities."""
from __future__ import annotations

import logging
from typing import Tuple

from flask import Flask, jsonify, request

from .task_identity import resolve_task_code

logging.basicConfig(level=logging.INFO)


def _error_response(message: str, status_code: int) -> Tuple[dict, int]:
    return {"ok": False, "error": message}, status_code


def create_app() -> Flask:
    app = Flask(__name__)

    @app.get("/tasks/resolve")
    def resolve_task():
        code = (request.args.get("code") or "").strip()
        if not code:
            body, status = _error_response("missing code", 400)
            return jsonify(body), status

        try:
            task = resolve_task_code(code)
        except LookupError as exc:
            body, status = _error_response(str(exc), 404)
        except ValueError as exc:
            body, status = _error_response(str(exc), 400)
        except Exception as exc:  # pylint: disable=broad-except
            logging.exception("Unexpected error while resolving task")
            body, status = _error_response(str(exc), 500)
        else:
            return jsonify({"ok": True, "task": task})

        return jsonify(body), status

    return app


if __name__ == "__main__":
    flask_app = create_app()
    flask_app.run(host="127.0.0.1", port=8031)
