"""Vikunja task identity resolver with self-healing identifiers."""
from __future__ import annotations

import os
from pathlib import Path
from typing import Dict, List, Optional, Set, Tuple

import requests
from dotenv import load_dotenv

VIKUNJA_BASE_URL = "http://eqbeelink1.tailb257ea.ts.net:8090"
ENV_PATH = Path("/home/squinlan/.local_secrets/vikunja.env")


def _load_token() -> str:
    """Load the Vikunja API token from the env file."""
    if not ENV_PATH.exists():
        raise FileNotFoundError(f"Missing Vikunja env file: {ENV_PATH}")

    load_dotenv(ENV_PATH)
    token = os.getenv("VIKUNJA_TOKEN")
    if not token:
        raise RuntimeError("VIKUNJA_TOKEN is not set in vikunja.env")
    return token


def _perform_request(
    method: str,
    path: str,
    token: str,
    *,
    params: Optional[dict] = None,
    json_body: Optional[dict] = None,
) -> requests.Response:
    url = f"{VIKUNJA_BASE_URL}{path}"
    headers = {"Authorization": f"Bearer {token}"}
    try:
        response = requests.request(
            method,
            url,
            headers=headers,
            params=params,
            json=json_body,
            timeout=5,
        )
    except requests.RequestException as exc:
        raise ConnectionError("Failed to query Vikunja API") from exc
    return response


def _ensure_success(response: requests.Response) -> None:
    try:
        response.raise_for_status()
    except requests.RequestException as exc:
        raise ConnectionError("Failed to query Vikunja API") from exc


def _response_to_list(response: requests.Response) -> List[Dict]:
    _ensure_success(response)
    payload = response.json()
    if not isinstance(payload, list):
        raise ValueError("Unexpected response format from Vikunja API")
    return payload


def _search_tasks(token: str, code: str) -> List[Dict]:
    response = _perform_request(
        "GET", "/api/v1/tasks", token, params={"search": code}
    )
    if response.status_code == 404:
        return []
    return _response_to_list(response)


def _fetch_project_tasks(token: str, project_id: int) -> List[Dict]:
    response = _perform_request(
        "GET", f"/api/v1/projects/{project_id}/tasks", token
    )
    if response.status_code == 404:
        return []
    return _response_to_list(response)


def _list_projects(token: str) -> List[Dict]:
    response = _perform_request("GET", "/api/v1/projects", token)
    if response.status_code == 404:
        return []
    return _response_to_list(response)


def _find_project_by_identifier(token: str, identifier: str) -> Optional[Dict]:
    if not identifier:
        return None
    response = _perform_request(
        "GET", "/api/v1/projects", token, params={"search": identifier}
    )
    if response.status_code == 404:
        return None
    projects = _response_to_list(response)
    for project in projects:
        if project.get("identifier") == identifier:
            return project
    return None


def _split_code(code: str) -> Tuple[Optional[str], Optional[str]]:
    if "-" not in code:
        return None, None
    prefix, suffix = code.rsplit("-", 1)
    if not prefix or not suffix:
        return None, None
    return prefix, suffix


def _infer_code_from_task(task: Dict) -> Optional[str]:
    project = task.get("project") or {}
    project_identifier = project.get("identifier")
    task_id = task.get("id")
    if not project_identifier or task_id is None:
        return None
    return f"{project_identifier}-{task_id}"


def _repair_identifier(task: Dict, inferred_code: str, token: str) -> Dict:
    task_id = task.get("id")
    if task_id is None:
        return task
    response = _perform_request(
        "PATCH", f"/api/v1/tasks/{task_id}", token, json_body={"identifier": inferred_code}
    )
    _ensure_success(response)
    task["identifier"] = inferred_code
    print(f"[task_identity] repaired identifier for task {task_id}: {inferred_code}")
    return task


def _select_task_from_candidates(tasks: List[Dict], code: str, token: str) -> Optional[Dict]:
    exact_matches = [task for task in tasks if (task.get("identifier") or "").strip() == code]
    if len(exact_matches) == 1:
        return exact_matches[0]
    if len(exact_matches) > 1:
        raise ValueError("Ambiguous task code")

    for task in tasks:
        identifier = (task.get("identifier") or "").strip()
        inferred = _infer_code_from_task(task)
        if inferred == code and identifier != code:
            return _repair_identifier(task, inferred, token)

    title_matches = [
        task for task in tasks if (task.get("title") or "").startswith(code)
    ]
    if len(title_matches) == 1:
        return title_matches[0]
    if len(title_matches) > 1:
        raise ValueError("Ambiguous task code")

    return None


def resolve_task_code(code: str) -> Dict:
    """Resolve a Vikunja task by identifier or inferred project prefix."""
    if not code:
        raise ValueError("Task code must be provided")

    token = _load_token()
    tasks = _search_tasks(token, code)
    match = _select_task_from_candidates(tasks, code, token)
    if match:
        return match

    checked_projects: Set[int] = set()
    for task in tasks:
        project = task.get("project") or {}
        project_id = project.get("id")
        if not project_id or project_id in checked_projects:
            continue
        checked_projects.add(project_id)
        project_tasks = _fetch_project_tasks(token, project_id)
        match = _select_task_from_candidates(project_tasks, code, token)
        if match:
            return match

    prefix, _ = _split_code(code)
    if prefix:
        project = _find_project_by_identifier(token, prefix)
        if project:
            project_id = project.get("id")
            if project_id and project_id not in checked_projects:
                project_tasks = _fetch_project_tasks(token, project_id)
                match = _select_task_from_candidates(project_tasks, code, token)
                if match:
                    return match

    raise LookupError("Task code could not be resolved or inferred")


def repair_missing_identifiers() -> List[Dict]:
    """Repair identifiers for all tasks missing or mismatching their inferred code."""
    token = _load_token()
    repairs: List[Dict] = []
    projects = _list_projects(token)
    for project in projects:
        project_id = project.get("id")
        if not project_id:
            continue
        tasks = _fetch_project_tasks(token, project_id)
        for task in tasks:
            inferred = _infer_code_from_task(task)
            identifier = (task.get("identifier") or "").strip()
            if not inferred or identifier == inferred:
                continue
            old_value = identifier or None
            _repair_identifier(task, inferred, token)
            repairs.append({"id": task.get("id"), "old": old_value, "new": inferred})
    return repairs
